<?php
namespace App\Services\AI;
use App\Models\{Conversation,Message,NotebookDocument,NotebookDocumentChunk,User}; use Illuminate\Http\UploadedFile; use Illuminate\Support\Collection; use Illuminate\Support\Facades\{DB,Http,Storage}; use Illuminate\Support\Str; use RuntimeException;
class NotebookService {
 private const RETRIEVAL_LIMIT=5;
 public function list(User $u,string $conversationId):Collection{$this->notebook($u,$conversationId);return NotebookDocument::where('conversation_id',$conversationId)->latest()->get()->map(fn($d)=>$this->data($d));}
 public function data(NotebookDocument $d):array{return ['id'=>$d->id,'conversation_id'=>$d->conversation_id,'original_filename'=>$d->original_filename,'size_bytes'=>$d->size_bytes,'status'=>$d->status,'error_message'=>$d->status==='failed'?$d->error_message:null,'title'=>$d->title,'summary'=>$d->summary,'chunk_count'=>$d->chunk_count,'notebook_title'=>$d->conversation?->title,'created_at'=>$d->created_at?->toISOString(),'updated_at'=>$d->updated_at?->toISOString()];}
 public function ingest(User $u,string $conversationId,UploadedFile $f):NotebookDocument {$notebook=$this->notebook($u,$conversationId);$isFirst=!$notebook->notebookDocuments()->exists();$id=(string)Str::uuid();$d=NotebookDocument::create(['id'=>$id,'user_id'=>$u->id,'conversation_id'=>$notebook->id,'original_filename'=>$f->getClientOriginalName()?:'document.pdf','storage_path'=>"notebook/{$u->id}/{$id}/source.pdf",'size_bytes'=>$f->getSize(),'status'=>'processing','chunk_count'=>0]);try{$stream=fopen($f->getRealPath(),'rb');Storage::disk('notebook')->put($d->storage_path,$stream);fclose($stream);$r=Http::withHeader('X-Service-Token',(string)config('services.ai.token'))->timeout(90)->attach('file',fopen($f->getRealPath(),'rb'),$d->original_filename,['Content-Type'=>'application/pdf'])->post(rtrim(AiServiceUrl::configured(),'/').'/v1/notebook/ingest');if($r->failed())throw new RuntimeException('Không thể xử lý PDF.');$p=$r->json();if(($p['dimensions']??0)!==384||!is_array($p['chunks']??null))throw new RuntimeException('Phản hồi xử lý tài liệu không hợp lệ.');DB::transaction(function()use($d,$p,$notebook,$isFirst){foreach($p['chunks'] as $c)NotebookDocumentChunk::create(['id'=>(string)Str::uuid(),'document_id'=>$d->id,'position'=>$c['position'],'page'=>$c['page'],'content'=>$c['content'],'content_hash'=>hash('sha256',$c['content']),'embedding'=>'['.implode(',',$c['embedding']).']']);$d->update(['status'=>'ready','title'=>$p['title'],'summary'=>$p['summary'],'chunk_count'=>count($p['chunks']),'error_message'=>null]);if($isFirst&&$notebook->title===null&&!empty($p['title']))$notebook->update(['title'=>Str::limit(trim((string)$p['title']),120,'')]);});}catch(\Throwable){$d->update(['status'=>'failed','error_message'=>'Không thể xử lý tài liệu.']);}return $d->fresh()->load('conversation');}
 public function delete(User $u,NotebookDocument $d):void {abort_unless($d->user_id===$u->id,404);try{Storage::disk('notebook')->delete($d->storage_path);}catch(\Throwable){throw new RuntimeException('Không thể xóa tệp.');}$d->delete();}
 public function query(User $u,string $conversationId,string $q,array $ids):array{$notebook=$this->notebook($u,$conversationId);$docs=NotebookDocument::where('conversation_id',$notebook->id)->where('status','ready')->when($ids,fn($x)=>$x->whereIn('id',$ids))->get();$answer='Không tìm thấy thông tin trong tài liệu đã chọn.';$citations=[];if($docs->isNotEmpty()){$vector=Http::withHeader('X-Service-Token',(string)config('services.ai.token'))->post(rtrim(AiServiceUrl::configured(),'/').'/v1/cv-rag/embed-query',['query'=>$q])->json('embedding');$v='['.implode(',',$vector).']';$candidates=$docs->flatMap(fn($d)=>NotebookDocumentChunk::where('document_id',$d->id)->select('*')->selectRaw('1 - (embedding OPERATOR(extensions.<=>) ?::extensions.vector) AS similarity',[$v])->orderByRaw('embedding OPERATOR(extensions.<=>) ?::extensions.vector',[$v])->limit(self::RETRIEVAL_LIMIT)->get());$chunks=$this->fairChunks($candidates);if($chunks->isNotEmpty()){$names=$docs->keyBy('id');$payload=$chunks->map(fn($c)=>['content'=>$c->content,'page'=>$c->page,'filename'=>$names[$c->document_id]->original_filename])->values()->all();$metadata=$docs->map(fn($d)=>['id'=>$d->id,'filename'=>$d->original_filename,'title'=>$d->title])->values()->all();$answer=Http::withHeader('X-Service-Token',(string)config('services.ai.token'))->post(rtrim(AiServiceUrl::configured(),'/').'/v1/notebook/answer',['question'=>$q,'documents'=>$metadata,'chunks'=>$payload])->json('answer')?:$answer;$citations=$chunks->map(fn($c)=>['document_id'=>$c->document_id,'filename'=>$names[$c->document_id]->original_filename,'page'=>$c->page])->unique(fn($c)=>$c['filename'].'|'.$c['page'])->values()->all();}}return DB::transaction(function()use($notebook,$q,$answer,$citations){$notebook=Conversation::whereKey($notebook->id)->lockForUpdate()->firstOrFail();$created=now()->startOfSecond();$next=((int)Message::where('conversation_id',$notebook->id)->max('sequence'))+1;$user=Message::create(['conversation_id'=>$notebook->id,'role'=>'user','content'=>$q,'sequence'=>$next,'created_at'=>$created]);$assistant=Message::create(['conversation_id'=>$notebook->id,'role'=>'assistant','content'=>$answer,'metadata'=>['citations'=>$citations],'sequence'=>$next+1,'created_at'=>$created->copy()->addSecond()]);$notebook->updated_at=$assistant->created_at;$notebook->save();return ['answer'=>$answer,'citations'=>$citations,'chat_history'=>[$user,$assistant],'conversation_title'=>$notebook->title];});}
 private function notebook(User $u,string $id):Conversation{return Conversation::whereKey($id)->where('user_id',$u->id)->where('mode','notebook')->firstOrFail();}
 private function fairChunks(Collection $candidates):Collection{$best=$candidates->groupBy('document_id')->map(fn($chunks)=>$chunks->sortByDesc('similarity')->first())->values();return $best->concat($candidates->sortByDesc('similarity')->reject(fn($chunk)=>$best->contains('id',$chunk->id)))->take(self::RETRIEVAL_LIMIT)->values();}
}
